class FakeNode { constructor(tag){this.tag=tag;this.children=[];this.textContent="";this.listeners={};this.attributes={};this.validity="";this.reported=false;} append(...nodes){this.children.push(...nodes);} replaceChildren(...nodes){this.children=[...nodes];} addEventListener(name,listener){this.listeners[name]=listener;} dispatch(name,event={preventDefault(){}}){return this.listeners[name](event);} setAttribute(name,value){this.attributes[name]=value;} removeAttribute(name){delete this.attributes[name];} setCustomValidity(value){this.validity=value;} reportValidity(){this.reported=true;} focus(){this.focused=true;} }
