function fakeDocument(root) { return { createElement:(tag)=>new FakeNode(tag), createTextNode:(text)=>({textContent:text}), querySelector:()=>root }; }
function findNode(root,predicate){if(predicate(root))return root;for(const child of root.children??[]){const found=findNode(child,predicate);if(found)return found;}}
