test("application entry flow covers landing, navigation, loading, errors, and failure-only retry", async()=>{const prior=globalThis.document;const root=new FakeNode("main"),location={hash:""};globalThis.document=fakeDocument(root);try{let routeListener;let resolveCheck;let checks=0;const api={check_neuron:()=>{checks++;return new Promise((resolve)=>{resolveCheck=resolve;});}};const app=createApplication({root,location,onHashChange:(_name,listener)=>{routeListener=listener;},actorFactory:async()=>api,authSession:signedOutAuth()});await app.start();assert.match(JSON.stringify(root),/Check an NNS neuron against the NNS Dendrite Standard/);const form=root.children.find((node)=>node.tag==="form"),input=form.children[0].children[0];input.value="01";form.dispatch("submit");assert.ok(input.reported);input.value="42";form.dispatch("submit");assert.equal(location.hash,"#/neuron/42");const pending=routeListener();assert.match(JSON.stringify(root),/Checking neuron 42…/);await Promise.resolve();resolveCheck({Ok:report("Compliant")});await pending;assert.match(JSON.stringify(root),/is compliant with the NNS Dendrite Standard/);assert.equal(findNode(root,(node)=>node.textContent==="Retry"),undefined);assert.doesNotMatch(JSON.stringify(root),/Check again|Refresh live analysis|Verify on-chain/);const errorLoad=app.loadNeuron("42");await Promise.resolve();resolveCheck({Err:{InvalidNeuronId:"live failure"}});await errorLoad;assert.match(JSON.stringify(root),/live failure/);const errorRetry=findNode(root,(node)=>node.tag==="button"&&node.textContent==="Retry");const recovered=errorRetry.dispatch("click");await Promise.resolve();resolveCheck({Ok:report()});await recovered;assert.match(JSON.stringify(root),/is compliant with the NNS Dendrite Standard/);assert.equal(checks,3);}finally{globalThis.document=prior;}});
test("actor creation failure is recoverable while successful construction stays cached",async()=>{const prior=globalThis.document;const root=new FakeNode("main"),location={hash:"#/neuron/42"};globalThis.document=fakeDocument(root);try{let creations=0;const api={check_neuron:async()=>({Ok:report()})};const app=createApplication({root,location,onHashChange:()=>{},actorFactory:async()=>{creations++;if(creations===1)throw new Error("agent creation failed");return api;},authSession:signedOutAuth()});await app.route();assert.match(JSON.stringify(root),/agent creation failed/);await findNode(root,(node)=>node.tag==="button"&&node.textContent==="Retry").dispatch("click");assert.match(JSON.stringify(root),/is compliant with the NNS Dendrite Standard/);await app.loadNeuron("42");assert.equal(creations,2);}finally{globalThis.document=prior;}});

test("route generations ignore out-of-order neuron and landing completions",async()=>{const prior=globalThis.document;const root=new FakeNode("main"),location={hash:"#/neuron/1"};globalThis.document=fakeDocument(root);try{const pending=new Map();const api={check_neuron:(id)=>new Promise((resolve)=>pending.set(id,resolve))};const app=createApplication({root,location,onHashChange:()=>{},actorFactory:async()=>api,authSession:signedOutAuth()});const a=app.route();await Promise.resolve();location.hash="#/neuron/2";const b=app.route();await Promise.resolve();pending.get(2n)({Ok:{...report("Compliant"),neuron_id:2n,standard_version:"route-b"}});await b;assert.match(JSON.stringify(root),/route-b/);pending.get(1n)({Ok:{...report("NonCompliant"),neuron_id:1n,standard_version:"route-a"}});await a;assert.match(JSON.stringify(root),/route-b/);assert.doesNotMatch(JSON.stringify(root),/route-a/);assert.equal(location.hash,"#/neuron/2");
location.hash="#/neuron/3";const c=app.route();await Promise.resolve();location.hash="";await app.route();pending.get(3n)({Ok:{...report(),neuron_id:3n,standard_version:"route-c"}});await c;assert.match(JSON.stringify(root),/Check an NNS neuron against the NNS Dendrite Standard/);assert.doesNotMatch(JSON.stringify(root),/route-c/);}finally{globalThis.document=prior;}});

