test("permanent origin failure disables login",async()=>{const prior=globalThis.document;const root=new FakeNode("main"),location={hash:""};globalThis.document=fakeDocument(root);try{let restored=false;const app=createApplication({root,location,onHashChange:()=>{},authSession:{configuration:{derivationOrigin:"https://dendrite.example"},originError:new Error("unapproved origin"),restore:async()=>{restored=true;}}});await app.start();assert.match(JSON.stringify(root),/unapproved origin/);assert.equal(findNode(root,(node)=>node.textContent==="Sign in with Internet Identity"),undefined);assert.equal(findNode(root,(node)=>node.textContent==="Try again"),undefined);assert.equal(restored,false);}finally{globalThis.document=prior;}});

test("startup restores identity before its single landing or neuron route",async()=>{const prior=globalThis.document;globalThis.document=fakeDocument(new FakeNode("unused"));try{const principal=(await import("@icp-sdk/core/principal")).Principal.fromText("aaaaa-aa");for(const hash of ["","#/neuron/42"]){const root=new FakeNode("main"),location={hash};globalThis.document=fakeDocument(root);let resolveRestore,resolveCheck,checks=0;const restore=new Promise((resolve)=>{resolveRestore=resolve;});const app=createApplication({root,location,onHashChange:()=>{},authSession:{configuration:{derivationOrigin:"https://dendrite.example"},restore:()=>restore,signIn:async()=>principal,signOut:async()=>{}},actorFactory:async()=>({check_neuron:()=>{checks++;return new Promise((resolve)=>{resolveCheck=resolve;});}})});const started=app.start();await Promise.resolve();assert.equal(root.children.length,0);assert.equal(checks,0);resolveRestore(principal);await Promise.resolve();await Promise.resolve();await Promise.resolve();if(hash){assert.match(JSON.stringify(root),/Checking neuron/);assert.doesNotMatch(JSON.stringify(root),/Check an NNS neuron against the NNS Dendrite Standard/);resolveCheck({Ok:report()});await started;assert.match(JSON.stringify(root),new RegExp(principal.toText()));}else{await started;assert.match(JSON.stringify(root),new RegExp(principal.toText()));assert.equal(checks,0);}}}finally{globalThis.document=prior;}});

test("failed sign-out retains the principal and remains retryable",async()=>{const prior=globalThis.document;const root=new FakeNode("main"),location={hash:""};globalThis.document=fakeDocument(root);try{const principal=(await import("@icp-sdk/core/principal")).Principal.fromText("aaaaa-aa");let attempts=0;const app=createApplication({root,location,onHashChange:()=>{},authSession:{configuration:{derivationOrigin:"https://dendrite.example"},restore:async()=>principal,signIn:async()=>principal,signOut:async()=>{attempts++;if(attempts===1)throw new Error("storage sign-out failed");}}});await app.start();await findNode(root,(node)=>node.textContent==="Sign out").dispatch("click");assert.match(JSON.stringify(root),new RegExp(principal.toText()));assert.match(JSON.stringify(root),/storage sign-out failed/);assert.ok(findNode(root,(node)=>node.textContent==="Sign out"));await findNode(root,(node)=>node.textContent==="Sign out").dispatch("click");assert.match(JSON.stringify(root),/Signed out/);assert.doesNotMatch(JSON.stringify(root),new RegExp(principal.toText()));}finally{globalThis.document=prior;}});

test("failed sign-out retains the authenticated actor but cancels the ready review",async()=>{const prior=globalThis.document;const root=new FakeNode("main"),location={hash:"#/neuron/42"};globalThis.document=fakeDocument(root);try{const {Principal}=await import("@icp-sdk/core/principal");const principal=Principal.selfAuthenticating(Uint8Array.from([9,8,7])),signingIdentity={getPrincipal:()=>principal},session={principal,signingIdentity,validate:async()=>true};let economics=0,calls=0;const live=managedReport(42n,principal);const nns={get_network_economics_parameters:async()=>{economics++;return{neuron_management_fee_per_proposal_e8s:1n};},manage_neuron:async()=>{calls++;return{command:[{MakeProposal:{proposal_id:[{id:1n}]}}]};}};const app=createApplication({root,location,onHashChange:()=>{},actorFactory:async()=>({check_neuron:async()=>({Ok:live})}),authSession:{configuration:{derivationOrigin:"https://dendrite.example"},restore:async()=>session,signOut:async()=>{throw new Error("sign-out storage failed");}},nnsActorFactory:async()=>nns});await app.start();findNode(root,(node)=>node.tag==="select"&&node.children?.some((child)=>child.textContent==="10 — Manager")).value="10";await findNode(root,(node)=>node.textContent==="Review voting-power refresh").dispatch("click");const oldSubmit=findNode(root,(node)=>node.textContent==="Submit exact reviewed request");findNode(root,(node)=>node.name==="confirmation").checked=true;assert.equal(economics,1);await findNode(root,(node)=>node.textContent==="Sign out").dispatch("click");assert.match(JSON.stringify(root),/sign-out storage failed/);await oldSubmit.dispatch("click");assert.equal(calls,0);findNode(root,(node)=>node.tag==="select"&&node.children?.some((child)=>child.textContent==="10 — Manager")).value="10";await findNode(root,(node)=>node.textContent==="Review voting-power refresh").dispatch("click");assert.equal(economics,2);assert.match(JSON.stringify(root),/Exact NNS request review/);}finally{globalThis.document=prior;}});

test("pending sign-out blocks detached submit, review, and duplicate transitions",async()=>{const prior=globalThis.document;try{const {Principal}=await import("@icp-sdk/core/principal");const principal=Principal.selfAuthenticating(Uint8Array.from([3,1,4])),signingIdentity={getPrincipal:()=>principal},session={principal,signingIdentity,validate:async()=>true};for(const failure of [false,true]){const root=new FakeNode("main"),location={hash:"#/neuron/42"};globalThis.document=fakeDocument(root);let resolveSignOut,rejectSignOut,signOuts=0,economics=0,calls=0;const nns={get_network_economics_parameters:async()=>{economics++;return{neuron_management_fee_per_proposal_e8s:1n};},manage_neuron:async()=>{calls++;return{command:[{MakeProposal:{proposal_id:[{id:1n}]}}]};}};const app=createApplication({root,location,onHashChange:()=>{},actorFactory:async()=>({check_neuron:async()=>({Ok:managedReport(42n,principal)})}),authSession:{configuration:{derivationOrigin:"https://dendrite.example"},restore:async()=>session,signOut:async()=>{signOuts++;return new Promise((resolve,reject)=>{resolveSignOut=resolve;rejectSignOut=reject;});}},nnsActorFactory:async()=>nns});await app.start();findNode(root,(node)=>node.tag==="select"&&node.children?.some((child)=>child.textContent==="10 — Manager")).value="10";const oldReview=findNode(root,(node)=>node.textContent==="Review voting-power refresh");await oldReview.dispatch("click");const oldSubmit=findNode(root,(node)=>node.textContent==="Submit exact reviewed request"),oldSignOut=findNode(root,(node)=>node.textContent==="Sign out");findNode(root,(node)=>node.name==="confirmation").checked=true;const transition=oldSignOut.dispatch("click");while(!resolveSignOut)await Promise.resolve();assert.match(JSON.stringify(root),/sign-out is in progress/);await oldSignOut.dispatch("click");assert.equal(signOuts,1);await oldSubmit.dispatch("click");await oldReview.dispatch("click");assert.equal(calls,0);assert.equal(economics,1);if(failure)rejectSignOut(new Error("held sign-out failed"));else resolveSignOut();await transition;if(failure){assert.match(JSON.stringify(root),/held sign-out failed/);assert.match(JSON.stringify(root),new RegExp(principal.toText()));findNode(root,(node)=>node.tag==="select"&&node.children?.some((child)=>child.textContent==="10 — Manager")).value="10";await findNode(root,(node)=>node.textContent==="Review voting-power refresh").dispatch("click");assert.equal(economics,2);}else assert.match(JSON.stringify(root),/Signed out/);}}finally{globalThis.document=prior;}});

test("sign-out cancels an owned preparation before awaiting browser storage",async()=>{const prior=globalThis.document;const root=new FakeNode("main"),location={hash:"#/neuron/42"};globalThis.document=fakeDocument(root);try{const {Principal}=await import("@icp-sdk/core/principal");const principal=Principal.selfAuthenticating(Uint8Array.from([2,7,1])),signingIdentity={getPrincipal:()=>principal},session={principal,signingIdentity,validate:async()=>true};let checks=0,resolvePreparation,resolveSignOut;const app=createApplication({root,location,onHashChange:()=>{},actorFactory:async()=>({check_neuron:async()=>++checks===1?{Ok:managedReport(42n,principal)}:new Promise((resolve)=>{resolvePreparation=resolve;})}),authSession:{configuration:{derivationOrigin:"https://dendrite.example"},restore:async()=>session,signOut:async()=>new Promise((resolve)=>{resolveSignOut=resolve;})},nnsActorFactory:async()=>({get_network_economics_parameters:async()=>({neuron_management_fee_per_proposal_e8s:1n})})});await app.start();findNode(root,(node)=>node.tag==="select"&&node.children?.some((child)=>child.textContent==="10 — Manager")).value="10";const preparing=findNode(root,(node)=>node.textContent==="Review voting-power refresh").dispatch("click");while(!resolvePreparation)await Promise.resolve();const signingOut=findNode(root,(node)=>node.textContent==="Sign out").dispatch("click");while(!resolveSignOut)await Promise.resolve();resolvePreparation({Ok:managedReport(42n,principal)});await preparing;assert.doesNotMatch(JSON.stringify(root),/Exact NNS request review/);resolveSignOut();await signingOut;assert.match(JSON.stringify(root),/Signed out/);}finally{globalThis.document=prior;}});

test("the actual main entry point bootstraps without a production auth hook",async()=>{const priorDocument=globalThis.document,priorLocation=globalThis.location,priorAdd=globalThis.addEventListener;const root=new FakeNode("main");globalThis.document=fakeDocument(root);globalThis.location={hash:"",origin:"https://dendrite.example"};globalThis.addEventListener=()=>{};try{await import(`../src/main.js?test=${Date.now()}`);await new Promise((resolve)=>setTimeout(resolve,0));assert.match(JSON.stringify(root),/Dendrite/);assert.doesNotMatch(readFileSync("canisters/dendrite/web/src/main.js","utf8"),/__DENDRITE_AUTH_SESSION__/);}finally{globalThis.document=priorDocument;globalThis.location=priorLocation;globalThis.addEventListener=priorAdd;}});

test("the production builder requires and generates explicit identity inputs without touching production assets",()=>{const base={...process.env};for(const key of ["DENDRITE_CANISTER_ID","CANISTER_ID_DENDRITE","DENDRITE_DERIVATION_ORIGIN","DENDRITE_ALTERNATIVE_ORIGINS_JSON","DENDRITE_IDENTITY_PROVIDER"])delete base[key];assert.notEqual(spawnSync(process.execPath,["canisters/dendrite/web/build-frontend.mjs"],{env:base}).status,0);const output=mkdtempSync(join(tmpdir(),"dendrite-frontend-test-"));try{const env={...base,...productionEnvironment,DENDRITE_ALTERNATIVE_ORIGINS_JSON:'["https://z.example","https://a.example"]',DENDRITE_FRONTEND_OUTPUT_DIR:output};const built=spawnSync(process.execPath,["canisters/dendrite/web/build-frontend.mjs"],{env,encoding:"utf8"});assert.equal(built.status,0,built.stderr);const manifest=JSON.parse(readFileSync(join(output,"asset-manifest.json"),"utf8"));const bundle=readFileSync(join(output,manifest["app.js"]),"utf8");assert.match(bundle,new RegExp(configuredPrincipal));assert.doesNotMatch(bundle,/__DENDRITE_AUTH_SESSION__/);assert.doesNotMatch(bundle,/include_all_manage_neuron_proposals:\[(?:true|!0)\]/);assert.equal(readFileSync(join(output,".well-known/ii-alternative-origins"),"utf8"),'{"alternativeOrigins":["https://a.example","https://z.example"]}');assert.doesNotMatch(bundle,/\?[^:]*:"aaaaa-aa"/);}finally{rmSync(output,{recursive:true,force:true});}});
test("each identity configuration input deterministically changes frontend bytes",()=>{const base={...process.env,...productionEnvironment};const variants=[base,{...base,DENDRITE_DERIVATION_ORIGIN:"https://other.example"},{...base,DENDRITE_ALTERNATIVE_ORIGINS_JSON:'["https://alt.example"]'},{...base,DENDRITE_BUILD_MODE:"local",DENDRITE_API_HOST:"http://localhost:4943",DENDRITE_FETCH_ROOT_KEY:"true",DENDRITE_DERIVATION_ORIGIN:"http://localhost:8000",DENDRITE_IDENTITY_PROVIDER:"http://localhost:4944/authorize"}];const outputs=[];try{for(const environment of variants){const output=mkdtempSync(join(tmpdir(),"dendrite-identity-input-"));outputs.push(output);const built=spawnSync(process.execPath,["canisters/dendrite/web/build-frontend.mjs"],{env:{...environment,DENDRITE_FRONTEND_OUTPUT_DIR:output},encoding:"utf8"});assert.equal(built.status,0,built.stderr);}const bundles=outputs.map((output)=>{const manifest=JSON.parse(readFileSync(join(output,"asset-manifest.json"),"utf8"));return createHash("sha256").update(readFileSync(join(output,manifest["app.js"]))).digest("hex");});assert.equal(new Set(bundles).size,variants.length);}finally{for(const output of outputs)rmSync(output,{recursive:true,force:true});}});
test("transaction IDL is generated exactly from reviewed Candid and consumed fields affect it",()=>{const output=mkdtempSync(join(tmpdir(),"dendrite-idl-"));try{const generated=join(output,"generated.js"),changedDid=join(output,"changed.did"),changed=join(output,"changed.js");let result=spawnSync("tools/scripts/generate-transaction-idl.sh",["candid/nns-governance/governance-transaction.subset.did",generated],{encoding:"utf8"});assert.equal(result.status,0,result.stderr);assert.equal(readFileSync(generated,"utf8"),readFileSync("src/declarations/nns-governance/nns-governance.did.js","utf8"));writeFileSync(changedDid,readFileSync("candid/nns-governance/governance-transaction.subset.did","utf8").replace("cached_neuron_stake_e8s : nat64","cached_neuron_stake_e8s : nat32"));result=spawnSync("tools/scripts/generate-transaction-idl.sh",[changedDid,changed],{encoding:"utf8"});assert.equal(result.status,0,result.stderr);assert.notEqual(readFileSync(changed,"utf8"),readFileSync(generated,"utf8"));assert.doesNotMatch(readFileSync(generated,"utf8"),/\['query'\]/);}finally{rmSync(output,{recursive:true,force:true});}});
